/*
 * Jonker-Volgenant algorithm for the linear assignment problem (minimization).
 * Adapted from the widely used lap.h implementation (public domain style,
 * originally by Roy Jonker, MagicLogic / Delft University of Technology).
 *
 * This is a self-contained translation of the classic integer JV code to doubles.
 */
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <algorithm>
#include <limits>

static const double BIG = 1e18;

extern "C" int lapjv_solve(int n, const double* cost, int* rowsol, int* colsol) {
    std::vector<double> u(n), v(n), d(n);
    std::vector<int> pred(n), free(n), collist(n);
    std::vector<int> matches(n);
    std::vector<char> unique(n);

    for (int i = 0; i < n; ++i) {
        rowsol[i] = -1;
        colsol[i] = -1;
        unique[i] = 1;
        u[i] = 0;
        v[i] = 0;
    }

    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) {
                minv = c;
                imin = i;
            }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            unique[imin] = 0;
        }
    }

    // REDUCTION TRANSFER
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1) {
            free[numfree++] = i;
        } else if (unique[i]) {
            int j1 = rowsol[i];
            double minv = BIG;
            for (int j = 0; j < n; ++j) {
                if (j == j1) continue;
                double red = cost[(size_t)i * n + j] - v[j];
                if (red < minv) minv = red;
            }
            v[j1] -= minv;
        }
    }

    // AUGMENTING ROW REDUCTION
    for (int f = 0; f < 2; ++f) {
        int k = 0;
        int prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            int i = free[k];
            k++;
            double umin = cost[(size_t)i * n + 0] - v[0];
            int j1 = 0;
            double usubmin = BIG;
            for (int j = 1; j < n; ++j) {
                double h = cost[(size_t)i * n + j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                    } else {
                        usubmin = umin;
                        umin = h;
                        j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            double vj1new = v[j1] - (usubmin - umin);
            bool vchange = std::fabs(vj1new - v[j1]) > 1e-12;
            if (i0 >= 0) {
                if (vchange) {
                    // put i0 back for another reduction in this scan
                    k--;
                    free[k] = i0;
                    rowsol[i] = j1;
                    colsol[j1] = i;
                    v[j1] = vj1new;
                    // i0 is now unassigned conceptually until reprocessed; clear its rowsol
                    rowsol[i0] = -1;
                } else if (usubmin - umin < 1e-12) {
                    // alternative optimum: assign to second best? keep i free, don't steal
                    // Actually both j1 and j2 have same reduced cost. Prefer not to displace.
                    // Find j2
                    int j2 = -1;
                    for (int j = 0; j < n; ++j) {
                        if (j == j1) continue;
                        double h = cost[(size_t)i * n + j] - v[j];
                        if (std::fabs(h - umin) < 1e-9) { j2 = j; break; }
                    }
                    if (j2 >= 0 && colsol[j2] < 0) {
                        rowsol[i] = j2;
                        colsol[j2] = i;
                    } else {
                        // displace anyway
                        rowsol[i] = j1;
                        colsol[j1] = i;
                        v[j1] = vj1new;
                        rowsol[i0] = -1;
                        free[numfree++] = i0;
                    }
                } else {
                    rowsol[i] = j1;
                    colsol[j1] = i;
                    v[j1] = vj1new;
                    rowsol[i0] = -1;
                    free[numfree++] = i0;
                }
            } else {
                rowsol[i] = j1;
                colsol[j1] = i;
                v[j1] = vj1new;
            }
        }
    }

    // Rebuild free list from actual unassigned rows (safety)
    numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) free[numfree++] = i;
        else colsol[rowsol[i]] = i;
    }
    for (int j = 0; j < n; ++j) {
        if (colsol[j] >= 0 && rowsol[colsol[j]] != j) colsol[j] = -1;
    }

    // AUGMENTATION
    for (int f = 0; f < numfree; ++f) {
        int freerow = free[f];
        // Dijkstra
        for (int j = 0; j < n; ++j) {
            d[j] = cost[(size_t)freerow * n + j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0;
        bool unassigned_found = false;
        int endofpath = -1;
        double minv = 0;
        int last = 0;

        do {
            if (up == low) {
                last = low - 1;
                minv = d[collist[up]];
                up = low;
                for (int k = low; k < n; ++k) {
                    int j = collist[k];
                    double h = d[j];
                    if (h <= minv) {
                        if (h < minv) {
                            up = low;
                            minv = h;
                        }
                        collist[k] = collist[up];
                        collist[up] = j;
                        up++;
                    }
                }
                for (int k = low; k < up; ++k) {
                    if (colsol[collist[k]] < 0) {
                        endofpath = collist[k];
                        unassigned_found = true;
                        break;
                    }
                }
            }
            if (!unassigned_found) {
                int j1 = collist[low];
                low++;
                int i = colsol[j1];
                double h = cost[(size_t)i * n + j1] - v[j1] - minv;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    double cred = cost[(size_t)i * n + j] - v[j] - h;
                    if (cred < d[j]) {
                        d[j] = cred;
                        pred[j] = i;
                        if (cred == minv) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                unassigned_found = true;
                                // move j into scanned frontier
                                collist[k] = collist[up];
                                collist[up++] = j;
                                break;
                            } else {
                                collist[k] = collist[up];
                                collist[up++] = j;
                            }
                        }
                    }
                }
            }
        } while (!unassigned_found);

        // update column prices
        for (int k = 0; k <= last; ++k) {
            int j1 = collist[k];
            v[j1] += d[j1] - minv;
        }

        // augmentation
        int j = endofpath;
        do {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            j = jnext;
        } while (i != freerow);
    }

    // verify
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -1;
    return 0;
}
