#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>
#include <cstdint>
#include <cstring>

// Fast auction algorithm for dense min-cost assignment.
// Parallel bidding with OpenMP.

#include <omp.h>

extern "C" int auction_solve(int n, const double* C, int* rowsol, double eps_target) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    std::vector<int> unassigned(n);
    std::vector<int> bid_j(n);
    std::vector<double> bid_p(n);
    std::vector<int> bid_i(n);

    double cmax = 0.0;
    #pragma omp parallel for reduction(max:cmax)
    for (int i = 0; i < n * n; ++i) {
        double v = std::fabs(C[i]);
        if (v > cmax) cmax = v;
    }
    if (cmax < eps_target) cmax = 1.0;
    double eps = cmax / 4.0;

    const int max_rounds = n * 30;

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;

        int rounds = 0;
        while (nun > 0 && rounds < max_rounds) {
            rounds++;
            // each unassigned person computes a bid
            #pragma omp parallel for schedule(static)
            for (int k = 0; k < nun; ++k) {
                int i = unassigned[k];
                const double* row = C + (size_t)i * n;
                int j1 = 0;
                double v1 = -std::numeric_limits<double>::infinity();
                double v2 = -std::numeric_limits<double>::infinity();
                for (int j = 0; j < n; ++j) {
                    double val = -row[j] - price[j];
                    if (val > v1) {
                        v2 = v1;
                        v1 = val;
                        j1 = j;
                    } else if (val > v2) {
                        v2 = val;
                    }
                }
                bid_j[k] = j1;
                bid_i[k] = i;
                bid_p[k] = price[j1] + (v1 - v2) + eps;
            }
            // resolve conflicts sequentially: highest bid per object
            // We'll scan and keep best. For speed use an array of best bid index.
            std::vector<int> best_k(n, -1);
            std::vector<double> best_p(n, -std::numeric_limits<double>::infinity());
            for (int k = 0; k < nun; ++k) {
                int j = bid_j[k];
                if (bid_p[k] > best_p[j]) {
                    best_p[j] = bid_p[k];
                    best_k[j] = k;
                }
            }
            for (int j = 0; j < n; ++j) {
                int k = best_k[j];
                if (k < 0) continue;
                int i = bid_i[k];
                int prev = owner[j];
                if (prev >= 0) assignment[prev] = -1;
                owner[j] = i;
                assignment[i] = j;
                price[j] = best_p[j];
            }
            nun = 0;
            for (int i = 0; i < n; ++i) {
                if (assignment[i] < 0) unassigned[nun++] = i;
            }
        }
        if (nun > 0) {
            // failed to assign at this epsilon
            return -1;
        }
        if (eps <= eps_target * 1.0000001) break;
        eps *= 0.25;
        if (eps < eps_target) eps = eps_target;
    }
    for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
    return 0;
}
