        double v = std::fabs(C[i]);
        if (v > cmax) cmax = v;
    }
    if (cmax < 1e-12) cmax = 1.0;
    double eps = std::max(cmax / 8.0, eps_target);

    // scratch for forward/reverse scan of best
    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;

        long long bids = 0;
        const long long max_bids = (long long)n * n * 8;
        int cursor = 0;
        while (nun > 0 && bids < max_bids) {
            // pick an unassigned person (cyclic)
            if (cursor >= nun) cursor = 0;
            int i = unassigned[cursor];
            const double* row = C + (size_t)i * n;

            int j1 = 0;
            double v1 = -std::numeric_limits<double>::infinity();
            double v2 = -std::numeric_limits<double>::infinity();
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > v1) {
