            owner[j1] = i;
            assignment[i] = j1;
            bids++;
            if (prev >= 0 && prev != i) {
                assignment[prev] = -1;
                // replace i in unassigned list with prev
                unassigned[cursor] = prev;
                cursor++;
            } else {
                // remove i from unassigned (swap with last)
                unassigned[cursor] = unassigned[nun - 1];
                nun--;
            }
        }
        if (nun > 0) return -1;
        if (eps <= eps_target * 1.0000001) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * 0.2;
        if (next < eps_target) next = eps_target;
