#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>
#include <cstdint>

// Jacobi (parallel-style) auction: all unassigned bid simultaneously.
// Fewer full passes than Gauss-Seidel when many are free, and we keep prices.
// Also uses a two-pointer best/second scan.

extern "C" int auction_solve(int n, const double* C, int* rowsol, double eps_target) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    std::vector<int> unassigned(n);
    std::vector<int> bid_j(n);
    std::vector<double> bid_p(n);
    std::vector<int> best_k(n);
    std::vector<double> best_p(n);

    double cmax = 0.0;
    for (int t = 0; t < n * n; ++t) {
        double v = std::fabs(C[t]);
        if (v > cmax) cmax = v;
    }
    if (cmax < 1e-12) cmax = 1.0;

    // epsilon scaling: geometric from cmax/n down
    double eps = cmax / 4.0;
    const double factor = 0.25;

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;

        int rounds = 0;
        const int max_rounds = n * 4 + 100;
        while (nun > 0 && rounds < max_rounds) {
            ++rounds;
            for (int k = 0; k < nun; ++k) {
                int i = unassigned[k];
                const double* row = C + (size_t)i * n;
                int j1 = 0;
                double v1 = -1e300;
                double v2 = -1e300;
                // manual unroll by 4
                int j = 0;
                for (; j + 3 < n; j += 4) {
                    double val0 = -row[j] - price[j];
                    double val1 = -row[j+1] - price[j+1];
                    double val2 = -row[j+2] - price[j+2];
                    double val3 = -row[j+3] - price[j+3];
                    if (val0 > v1) { v2 = v1; v1 = val0; j1 = j; }
                    else if (val0 > v2) v2 = val0;
                    if (val1 > v1) { v2 = v1; v1 = val1; j1 = j+1; }
                    else if (val1 > v2) v2 = val1;
                    if (val2 > v1) { v2 = v1; v1 = val2; j1 = j+2; }
                    else if (val2 > v2) v2 = val2;
                    if (val3 > v1) { v2 = v1; v1 = val3; j1 = j+3; }
                    else if (val3 > v2) v2 = val3;
                }
                for (; j < n; ++j) {
                    double val = -row[j] - price[j];
                    if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                    else if (val > v2) v2 = val;
                }
                bid_j[k] = j1;
                bid_p[k] = price[j1] + (v1 - v2) + eps;
            }
            std::fill(best_k.begin(), best_k.end(), -1);
            std::fill(best_p.begin(), best_p.end(), -1e300);
            for (int k = 0; k < nun; ++k) {
                int j = bid_j[k];
                double p = bid_p[k];
                if (p > best_p[j]) {
                    best_p[j] = p;
                    best_k[j] = k;
                }
            }
            for (int j = 0; j < n; ++j) {
                int k = best_k[j];
                if (k < 0) continue;
                int i = unassigned[k];
                int prev = owner[j];
                if (prev >= 0) assignment[prev] = -1;
                // if i was assigned to something else this round, clear it
                int cur = assignment[i];
                if (cur >= 0 && cur != j) {
                    // i won two? shouldn't, each person bids once. ignore
                }
                owner[j] = i;
                assignment[i] = j;
                price[j] = best_p[j];
            }
            int w = 0;
            for (int i = 0; i < n; ++i) if (assignment[i] < 0) unassigned[w++] = i;
            nun = w;
        }
        if (nun > 0) return -1;
        if (eps <= eps_target * 1.0000001) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
}
