#include <cstdint>
#include <vector>
#include <algorithm>
#include <limits>

// Gauss-Seidel auction with epsilon scaling.
// Hot loop: scan one row of -C - price for best and second best.

extern "C" int auction_solve(int n, const double* C, int* rowsol, double eps_target) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    std::vector<int> unassigned(n);

    double cmax = 0.0;
    // sample a subset for scale to save time? full scan is n^2 and cheap vs auction
    for (int i = 0; i < n * n; i += 17) {
        double v = std::fabs(C[i]);
        if (v > cmax) cmax = v;
    }
    // ensure cmax is a true upper by a few random? use a conservative full max on first row-col
    for (int i = 0; i < n; ++i) {
        double v = std::fabs(C[(size_t)i * n + i]);
        if (v > cmax) cmax = v;
    }
    if (cmax < 1e-12) cmax = 1.0;
    // bump to be safe
    cmax *= 1.5;

    double eps = cmax * 0.25;
    const double factor = 0.15; // more aggressive scaling = fewer phases

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int cursor = 0;
        long long bids = 0;
        const long long max_bids = (long long)n * n * 4;

        while (nun > 0 && bids < max_bids) {
            if (cursor >= nun) cursor = 0;
            int i = unassigned[cursor];
            const double* row = C + (size_t)i * n;

            int j1 = 0;
            double v1 = -1e300, v2 = -1e300;
            const double* pr = price.data();
            int j = 0;
            // unroll 4
            int n4 = n & ~3;
            for (; j < n4; j += 4) {
                double a0 = -row[j] - pr[j];
                double a1 = -row[j+1] - pr[j+1];
                double a2 = -row[j+2] - pr[j+2];
                double a3 = -row[j+3] - pr[j+3];
                if (a0 > v1) { v2 = v1; v1 = a0; j1 = j; }
                else if (a0 > v2) { v2 = a0; }
                if (a1 > v1) { v2 = v1; v1 = a1; j1 = j+1; }
                else if (a1 > v2) { v2 = a1; }
                if (a2 > v1) { v2 = v1; v1 = a2; j1 = j+2; }
                else if (a2 > v2) { v2 = a2; }
                if (a3 > v1) { v2 = v1; v1 = a3; j1 = j+3; }
                else if (a3 > v2) { v2 = a3; }
            }
            for (; j < n; ++j) {
                double a = -row[j] - pr[j];
                if (a > v1) { v2 = v1; v1 = a; j1 = j; }
                else if (a > v2) v2 = a;
            }

            double bid = pr[j1] + (v1 - v2) + eps;
            int prev = owner[j1];
            price[j1] = bid;
            owner[j1] = i;
            assignment[i] = j1;
            ++bids;
            if (prev >= 0 && prev != i) {
                assignment[prev] = -1;
                unassigned[cursor] = prev;
                ++cursor;
            } else {
                unassigned[cursor] = unassigned[--nun];
            }
        }
        if (nun > 0) return -1;
        if (eps <= eps_target) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
