// Min-cost assignment on a sparse bipartite graph (each left node has a list of candidate right nodes).
// Successive shortest paths with potentials (Dijkstra + reduced costs).
// If the candidate graph has no perfect matching, returns -1.
#include <vector>
#include <cstdint>
#include <cmath>
#include <queue>
#include <limits>
#include <algorithm>

struct Edge {
    int to;
    double w;
};

extern "C" int sparse_assign(
    int n,
    const int* offsets,   // n+1
    const int* targets,   // offsets[n]
    const double* weights,
    int* rowsol,
    int* colsol
) {
    int m = offsets[n];
    std::vector<std::vector<std::pair<int,double>>> adj(n);
    for (int i = 0; i < n; ++i) {
        adj[i].reserve(offsets[i+1] - offsets[i]);
        for (int e = offsets[i]; e < offsets[i+1]; ++e) {
            adj[i].emplace_back(targets[e], weights[e]);
        }
    }
    std::vector<double> pot(n, 0.0); // potentials on right
    std::vector<int> owner(n, -1);   // left assigned to right
    std::fill(rowsol, rowsol+n, -1);
    std::fill(colsol, colsol+n, -1);

    const double INF = 1e100;

    for (int src = 0; src < n; ++src) {
        std::vector<double> dist(n, INF);
        std::vector<int> prev_right(n, -1); // left node that leads to this right in shortest path? 
        std::vector<int> prev_left_of_right(n, -1);
        std::vector<char> done(n, 0);

        using QN = std::pair<double,int>;
        std::priority_queue<QN, std::vector<QN>, std::greater<QN>> pq;

        // edges from src
        for (auto [j, w] : adj[src]) {
            double rd = w - pot[j]; // left potential 0 for free source; we keep only right potentials
            if (rd < dist[j]) {
                dist[j] = rd;
                prev_left_of_right[j] = src;
                pq.emplace(rd, j);
            }
        }

        int sink = -1;
        while (!pq.empty()) {
            auto [d, j] = pq.top(); pq.pop();
            if (done[j]) continue;
            if (d > dist[j]) continue;
            done[j] = 1;
            if (colsol[j] < 0) { sink = j; break; }
            int i = colsol[j]; // matched left, must leave via its other edges, paying -matched edge
            // reduced cost of traversing matched edge backward: -(w_matched - pot[j]) = -w_matched + pot[j]
            // then forward edge i->j2: w2 - pot[j2]
            // total add = w2 - pot[j2] - w_matched + pot[j]
            double w_matched = 0;
            // find matched weight
            // store it: we can recompute by scan (k small)
            for (auto [jj, w] : adj[i]) if (jj == j) { w_matched = w; break; }
            double base = d - w_matched + pot[j];
            for (auto [j2, w2] : adj[i]) {
                if (j2 == j) continue;
                double nd = base + w2 - pot[j2];
                if (nd < dist[j2]) {
                    dist[j2] = nd;
                    prev_left_of_right[j2] = i;
                    pq.emplace(nd, j2);
                }
            }
        }
        if (sink < 0) return -1;

        // update potentials
        double dsink = dist[sink];
        for (int j = 0; j < n; ++j) {
            if (done[j]) pot[j] += dist[j] - dsink;
        }

        // augment
        int j = sink;
        while (true) {
            int i = prev_left_of_right[j];
            int jprev = rowsol[i];
            rowsol[i] = j;
            colsol[j] = i;
            if (i == src) break;
            j = jprev;
        }
    }
    return 0;
}
