// Successive shortest augmenting paths for sparse min-cost bipartite assignment.
// Left nodes 0..n-1, right nodes 0..n-1.
// Each left node i has edges to a subset of right nodes.
//
// Potentials pi_left[i], pi_right[j].
// Reduced cost of forward edge i->j: w - pi_left[i] - pi_right[j]  ? 
// We'll use the common formulation:
//   dual u[i] for left, v[j] for right
//   reduced cost c_ij - u_i - v_j >= 0 for non-matched? For minimization SSP:
//   Maintain v[j] (right potentials). Reduced cost of i->j is w_ij - v[j] + v[matched]? 
//
// Clean version from "Assignment Problem" successive shortest paths:
//   Let dual variables y[j] on the right (initialized 0).
//   Reduced cost rc(i,j) = w(i,j) - y[j].
//   When traversing a matched edge backward j->i, the cost is -(w - y[j]) = -w + y[j],
//   then from i forward to j2: w2 - y[j2].
//   After Dijkstra distances dist[j] (on right nodes), update y[j] += dist[j] - dist[sink]
//   for all j with dist[j] < INF that were settled with dist <= dist[sink].
//
// The bug before may have been updating only `done` nodes whose dist could exceed dist[sink]
// if they were popped after... we break at sink so done nodes have dist <= dist[sink].
// Let's add left potentials too for numerical stability and follow CLRS-style carefully.
//
// Implementation plan (Kuhn-Munkres SSP):
// graph edges only forward left->right with cost w.
// matching M.
// potentials p[right].
// For a free left src:
//   Dijkstra on residual:
//     start: for each edge src->j, dist[j] = w - p[j], parent[j] = src
//     When relaxing from a matched right j (matched to i):
//        the residual backward doesn't go to a node we search; we immediately relax i's forward edges.
//        newdist[j2] = dist[j] + w(i,j2) - p[j2] - (w(i,j) - p[j])
//   This is what we had. Why wrong?
//
// Let me test the formula on a tiny instance by also storing slack and verifying complementary slackness.
// I'll add a debug mode.
//
// WAIT. I think the potential update sign / application is inconsistent with initialization.
// Initially p=0. First augmentation: dist = w, sink = argmin w from src. Update p[j] += dist[j] - dist[sink]
// so p[sink] stays 0, others that are larger get positive? dist[j] - dist[sink] >= 0 so p increases.
// Reduced costs w - p become smaller for non-sink. That's OK for minimization? 
// Standard reference (e.g. https://cp-algorithms.com/graph/min_cost_flow.html) uses potentials
// added so reduced costs stay nonnegative: potential[v] += dist[v] after Dijkstra where dist are reduced distances.
// For assignment, a known-good snippet is the dense JV which we know works. For sparse, let me port
// a known min-cost flow successive shortest path with Johnson potentials.

#include <vector>
#include <queue>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <limits>

struct Adj {
    std::vector<int> to;
    std::vector<double> w;
    std::vector<int> rev; // index of reverse edge in opposite adj? we'll use separate left/right adj
};

extern "C" int sparse_assign(
    int n,
    const int* offsets,
    const int* targets,
    const double* weights,
    int* rowsol,
    int* colsol
) {
    // Build residual as edge lists on left only; right has match pointer.
    std::vector<std::vector<std::pair<int,double>>> adj(n);
    for (int i = 0; i < n; ++i) {
        for (int e = offsets[i]; e < offsets[i+1]; ++e)
            adj[i].emplace_back(targets[e], weights[e]);
    }

    const double INF = 1e100;
    std::vector<double> potL(n, 0.0), potR(n, 0.0);
    std::fill(rowsol, rowsol + n, -1);
    std::fill(colsol, colsol + n, -1);

    for (int src = 0; src < n; ++src) {
        std::vector<double> distR(n, INF), distL(n, INF);
        std::vector<int> preR(n, -1); // left predecessor of right
        std::vector<int> preL(n, -1); // right predecessor of left (matched)
        std::vector<char> visR(n, 0), visL(n, 0);

        using P = std::pair<double, int>; // dist, node id (left: 0..n-1, right: n..2n-1)
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

        distL[src] = 0;
        pq.emplace(0.0, src); // left nodes encoded 0..n-1, right n..2n-1

        int sinkR = -1;
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (u < n) {
                // left node
                if (visL[u] || d > distL[u]) continue;
                visL[u] = 1;
                for (auto [j, w] : adj[u]) {
                    double nd = d + w - potL[u] - potR[j];
                    if (nd < distR[j]) {
                        distR[j] = nd;
                        preR[j] = u;
                        pq.emplace(nd, n + j);
                    }
                }
            } else {
                int j = u - n;
                if (visR[j] || d > distR[j]) continue;
                visR[j] = 1;
                if (colsol[j] < 0) { sinkR = j; break; }
                int i = colsol[j];
                // backward residual edge j -> i with cost -(w - potL[i] - potR[j]) = -w + potL[i] + potR[j]
                double wmatch = 0;
                for (auto [jj, w] : adj[i]) if (jj == j) { wmatch = w; break; }
                double nd = d + (-wmatch + potL[i] + potR[j]);
                if (nd < distL[i]) {
                    distL[i] = nd;
                    preL[i] = j;
                    pq.emplace(nd, i);
                }
            }
        }
        if (sinkR < 0) return -1;

        // update potentials for visited nodes
        // pot += dist for visited, so reduced costs remain nonnegative
        for (int i = 0; i < n; ++i) if (visL[i]) potL[i] += distL[i];
        for (int j = 0; j < n; ++j) if (visR[j]) potR[j] += distR[j];
        // nodes not visited: to keep dual feasible relative to sink, add dist[sink]
        // Standard Johnson: potential[v] += dist[v] for all v reached; unreached unchanged
        // because their dist is INF. OK if we only require reduced costs of settled edges.

        // augment along path
        int j = sinkR;
        while (true) {
            int i = preR[j];
            int jprev = rowsol[i];
            rowsol[i] = j;
            colsol[j] = i;
            if (i == src) break;
            j = preL[i];
            (void)jprev;
        }
    }
    return 0;
}
