// Successive shortest paths, ported from the verified Python version.
// Right-node Dijkstra only. Potential update: pot[j] += dist[j] - dist[sink] for settled nodes.
#include <vector>
#include <queue>
#include <cstdint>
#include <algorithm>
#include <cmath>

extern "C" int sparse_assign(
    int n,
    const int* offsets,
    const int* targets,
    const double* weights,
    int* rowsol,
    int* colsol
) {
    std::vector<std::vector<std::pair<int,double>>> adj(n);
    for (int i = 0; i < n; ++i) {
        int a = offsets[i], b = offsets[i+1];
        adj[i].reserve(b - a);
        for (int e = a; e < b; ++e)
            adj[i].emplace_back(targets[e], weights[e]);
    }

    const double INF = 1e100;
    std::vector<double> pot(n, 0.0);
    std::fill(rowsol, rowsol + n, -1);
    std::fill(colsol, colsol + n, -1);

    std::vector<double> dist(n);
    std::vector<int> prev(n);
    std::vector<char> done(n);

    using P = std::pair<double,int>;

    for (int src = 0; src < n; ++src) {
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(prev.begin(), prev.end(), -1);
        std::fill(done.begin(), done.end(), 0);
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

        for (auto [j, w] : adj[src]) {
            double rd = w - pot[j];
            if (rd < dist[j]) {
                dist[j] = rd;
                prev[j] = src;
                pq.emplace(rd, j);
            }
        }

        int sink = -1;
        while (!pq.empty()) {
            auto [d, j] = pq.top(); pq.pop();
            if (done[j] || d > dist[j]) continue;
            done[j] = 1;
            if (colsol[j] < 0) { sink = j; break; }
            int i = colsol[j];
            double w_m = 0.0;
            bool found = false;
            for (auto [jj, w] : adj[i]) if (jj == j) { w_m = w; found = true; break; }
            if (!found) return -2;
            double base = d - (w_m - pot[j]);
            for (auto [j2, w2] : adj[i]) {
                double nd = base + (w2 - pot[j2]);
                if (nd < dist[j2] - 1e-15) {
                    dist[j2] = nd;
                    prev[j2] = i;
                    pq.emplace(nd, j2);
                }
            }
        }
        if (sink < 0) return -1;

        double ds = dist[sink];
        for (int j = 0; j < n; ++j) if (done[j]) pot[j] += dist[j] - ds;

        int j = sink;
        while (true) {
            int i = prev[j];
            int jprev = rowsol[i];
            rowsol[i] = j;
            colsol[j] = i;
            if (i == src) break;
            j = jprev;
        }
    }
    return 0;
}
