// Fast squared-euclidean kNN (2D) + successive shortest path assignment.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <queue>

struct Node {
    double x, y;
    int idx;
};

static void knn_one(const double* sp, const Node* nodes, int n, int k,
                    int* out_idx, double* out_d2) {
    // partial selection of k nearest among n using a max-heap of size k
    // For n=600, k=64, a simple scan with heap is fine but we want faster.
    // Use std::partial_sort on a copied distance array? n=600 is small: 
    // computing all d2 and nth_element is very fast.
}

extern "C" int solve_emd_points(
    int n,
    const double* sp, // n*2
    const double* tp, // n*2
    int k,
    int* rowsol,
    double* out_cost_optional // nullable
) {
    if (k > n) k = n;
    if (k < 1) return -1;

    // compute all squared distances and take k nearest per row via nth_element
    // Memory: n*n doubles = 600*600*8 = 2.8MB, fine.
    std::vector<double> D((size_t)n * n);
    for (int i = 0; i < n; ++i) {
        double sx = sp[2*i], sy = sp[2*i+1];
        double* row = D.data() + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            double dx = sx - tp[2*j];
            double dy = sy - tp[2*j+1];
            row[j] = dx*dx + dy*dy;
        }
    }

    std::vector<int> nn_idx((size_t)n * k);
    std::vector<double> nn_w((size_t)n * k);
    std::vector<int> order(n);
    for (int i = 0; i < n; ++i) {
        double* row = D.data() + (size_t)i * n;
        for (int j = 0; j < n; ++j) order[j] = j;
        std::nth_element(order.begin(), order.begin() + k, order.end(),
                         [&](int a, int b){ return row[a] < row[b]; });
        // sort the k for stability of ties (smaller index first on equal dist) 
        std::sort(order.begin(), order.begin() + k, [&](int a, int b){
            if (row[a] < row[b]) return true;
            if (row[b] < row[a]) return false;
            return a < b;
        });
        for (int t = 0; t < k; ++t) {
            nn_idx[(size_t)i * k + t] = order[t];
            nn_w[(size_t)i * k + t] = row[order[t]];
        }
    }

    // If the reference match might need a farther neighbor, caller chooses k.
    // SSP assignment on the sparse graph.
    const double INF = 1e100;
    std::vector<double> pot(n, 0.0);
    std::vector<int> colsol(n, -1);
    std::fill(rowsol, rowsol + n, -1);

    std::vector<double> dist(n);
    std::vector<int> prev(n);
    std::vector<char> done(n);
    using P = std::pair<double,int>;

    for (int src = 0; src < n; ++src) {
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(prev.begin(), prev.end(), -1);
        std::fill(done.begin(), done.end(), 0);
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

        const int* idxrow = nn_idx.data() + (size_t)src * k;
        const double* wrow = nn_w.data() + (size_t)src * k;
        for (int t = 0; t < k; ++t) {
            int j = idxrow[t];
            double rd = wrow[t] - pot[j];
            dist[j] = rd;
            prev[j] = src;
            pq.emplace(rd, j);
        }
        int sink = -1;
        while (!pq.empty()) {
            auto [d, j] = pq.top(); pq.pop();
            if (done[j] || d > dist[j]) continue;
            done[j] = 1;
            if (colsol[j] < 0) { sink = j; break; }
            int i = colsol[j];
            // matched weight
            const int* iidx = nn_idx.data() + (size_t)i * k;
            const double* iw = nn_w.data() + (size_t)i * k;
            double w_m = 0;
            bool found = false;
            for (int t = 0; t < k; ++t) if (iidx[t] == j) { w_m = iw[t]; found = true; break; }
            if (!found) return -2;
            double base = d - (w_m - pot[j]);
            for (int t = 0; t < k; ++t) {
                int j2 = iidx[t];
                double nd = base + (iw[t] - pot[j2]);
                if (nd < dist[j2] - 1e-15) {
                    dist[j2] = nd;
                    prev[j2] = i;
                    pq.emplace(nd, j2);
                }
            }
        }
        if (sink < 0) return -1;
        double ds = dist[sink];
        for (int j = 0; j < n; ++j) if (done[j]) pot[j] += dist[j] - ds;
        int j = sink;
        while (true) {
            int i = prev[j];
            int jprev = rowsol[i];
            rowsol[i] = j;
            colsol[j] = i;
            if (i == src) break;
            j = jprev;
        }
    }
    return 0;
}
