// Optimized sparse successive-shortest-path assignment + squared distance kNN.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <queue>

extern "C" int solve_from_cost(int n, const double* C, int k, int* rowsol) {
    if (k > n) k = n;
    // kNN by squared-cost proxy: since euclidean is monotone in squared, nearest by C is nearest by C^2.
    // We select k smallest C per row.
    std::vector<int> nn_idx((size_t)n * k);
    std::vector<double> nn_w((size_t)n * k);
    std::vector<int> order(n);

    for (int i = 0; i < n; ++i) {
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; ++j) order[j] = j;
        std::nth_element(order.begin(), order.begin() + (k - 1), order.end(),
                         [&](int a, int b){ return row[a] < row[b]; });
        std::sort(order.begin(), order.begin() + k, [&](int a, int b){
            if (row[a] < row[b]) return true;
            if (row[b] < row[a]) return false;
            return a < b;
        });
        for (int t = 0; t < k; ++t) {
            int j = order[t];
            nn_idx[(size_t)i * k + t] = j;
            nn_w[(size_t)i * k + t] = row[j];
        }
    }

    const double INF = 1e100;
    std::vector<double> pot(n, 0.0);
    std::vector<int> colsol(n, -1);
    std::fill(rowsol, rowsol + n, -1);
    std::vector<double> dist(n);
    std::vector<int> prev(n);
    std::vector<char> done(n);

    // matched edge position for O(1) weight lookup: col -> position in that row's nn list, or -1
    // We'll store match_pos[j] = t such that nn_idx[colsol[j]*k + t] == j
    std::vector<int> match_t(n, -1);

    using P = std::pair<double,int>;
    std::vector<P> heap;
    heap.reserve(n * 4);

    for (int src = 0; src < n; ++src) {
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(prev.begin(), prev.end(), -1);
        std::fill(done.begin(), done.end(), 0);
        heap.clear();

        const int* idxrow = nn_idx.data() + (size_t)src * k;
        const double* wrow = nn_w.data() + (size_t)src * k;
        for (int t = 0; t < k; ++t) {
            int j = idxrow[t];
            double rd = wrow[t] - pot[j];
            dist[j] = rd;
            prev[j] = src;
            heap.emplace_back(rd, j);
        }
        std::make_heap(heap.begin(), heap.end(), std::greater<P>());

        int sink = -1;
        while (!heap.empty()) {
            std::pop_heap(heap.begin(), heap.end(), std::greater<P>());
            auto [d, j] = heap.back();
            heap.pop_back();
            if (done[j] || d > dist[j]) continue;
            done[j] = 1;
            if (colsol[j] < 0) { sink = j; break; }
            int i = colsol[j];
            int tmatch = match_t[j];
            const int* iidx = nn_idx.data() + (size_t)i * k;
            const double* iw = nn_w.data() + (size_t)i * k;
            double w_m = iw[tmatch];
            double base = d - (w_m - pot[j]);
            for (int t = 0; t < k; ++t) {
                int j2 = iidx[t];
                double nd = base + (iw[t] - pot[j2]);
                if (nd < dist[j2]) {
                    dist[j2] = nd;
                    prev[j2] = i;
                    heap.emplace_back(nd, j2);
                    std::push_heap(heap.begin(), heap.end(), std::greater<P>());
                }
            }
        }
        if (sink < 0) return -1;
        double ds = dist[sink];
        for (int j = 0; j < n; ++j) if (done[j]) pot[j] += dist[j] - ds;

        int j = sink;
        while (true) {
            int i = prev[j];
            int jprev = rowsol[i];
            rowsol[i] = j;
            colsol[j] = i;
            // find t
            const int* iidx = nn_idx.data() + (size_t)i * k;
            int tfound = -1;
            for (int t = 0; t < k; ++t) if (iidx[t] == j) { tfound = t; break; }
            match_t[j] = tfound;
            if (i == src) break;
            j = jprev;
        }
    }
    return 0;
}
