// Jonker-Volgenant LAP (minimization), double costs.
// Structure follows the classic lap.cpp (Jonker & Volgenant / MagicLogic),
// translated carefully from the integer version.
#include <vector>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <limits>

extern "C" int jv_solve(int dim, const double* cost, int* rowsol) {
    const double INF = 1e100;
    const int n = dim;
    std::vector<int> colsol(n);
    std::vector<double> d(n), v(n);
    std::vector<int> pred(n), free_rows, collist(n);
    std::vector<char> unique(n, 1);
    free_rows.reserve(n);

    for (int i = 0; i < n; ++i) {
        rowsol[i] = -1;
        colsol[i] = -1;
        v[i] = 0;
    }

    // Column reduction
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            unique[imin] = 0;
        }
    }

    // Reduction transfer
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1) {
            free_rows.push_back(i);
        } else if (unique[i]) {
            int j = rowsol[i];
            double minv = INF;
            const double* row = cost + (size_t)i * n;
            for (int j2 = 0; j2 < n; ++j2) {
                if (j2 == j) continue;
                double red = row[j2] - v[j2];
                if (red < minv) minv = red;
            }
            v[j] -= minv;
        }
    }

    // Augmenting row reduction (2 scans), faithful control flow
    for (int loop = 0; loop < 2; ++loop) {
        int k = 0;
        int prv = (int)free_rows.size();
        int nfree_new = 0;
        std::vector<int> newfree;
        newfree.reserve(prv);
        // We process a dynamic list: use index into free_rows which we may extend? 
        // Classic code uses an array and decrements k to reprocess.
        // Implement with a deque-like vector and an explicit next index that can go backwards.
        std::vector<int> list = free_rows;
        int kend = (int)list.size();
        k = 0;
        std::vector<int> deferred;
        while (k < kend) {
            int i = list[k++];
            const double* row = cost + (size_t)i * n;
            double u1 = row[0] - v[0];
            int j1 = 0;
            double u2 = INF;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < u2) {
                    if (h >= u1) {
                        u2 = h;
                    } else {
                        u2 = u1;
                        u1 = h;
                        j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            double vnew = v[j1] - (u2 - u1);
            bool vchange = vnew < v[j1] - 1e-15;
            if (i0 >= 0) {
                if (vchange) {
                    v[j1] = vnew;
                    rowsol[i] = j1;
                    colsol[j1] = i;
                    rowsol[i0] = -1;
                    // reprocess i0 immediately: put it at current position by stepping back
                    list[--k] = i0; // k was incremented, --k points at just-consumed slot
                    // next iteration k++ reads i0. Good.
                } else if (u2 - u1 < 1e-15) {
                    // find first free or any second with equal reduced cost
                    int j2 = -1;
                    for (int j = 0; j < n; ++j) {
                        if (j == j1) continue;
                        if (std::fabs((row[j] - v[j]) - u1) <= 1e-12) { j2 = j; break; }
                    }
                    if (j2 >= 0 && colsol[j2] < 0) {
                        rowsol[i] = j2;
                        colsol[j2] = i;
                    } else {
                        v[j1] = vnew;
                        rowsol[i] = j1;
                        colsol[j1] = i;
                        rowsol[i0] = -1;
