            if (!found) {
                int j1 = collist[low++];
                int i = colsol[j1];
                double h = cost[(size_t)i * n + j1] - v[j1] - minv;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    double cred = cost[(size_t)i * n + j] - v[j] - h;
                    if (cred < d[j]) {
                        d[j] = cred;
                        pred[j] = i;
                        if (cred == minv) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                found = true;
                                collist[k] = collist[up];
                                collist[up++] = j;
                                break;
                            } else {
                                collist[k] = collist[up];
                                collist[up++] = j;
                            }
                        }
                    }
                }
            }
        } while (!found && low < n);
        if (!found) return -1;

        for (int k = 0; k <= last; ++k) {
            int j1 = collist[k];
            v[j1] += d[j1] - minv;
        }
        int j = endofpath;
        int i;
        do {
            i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            j = jnext;
        } while (i != freerow);
    }
    return 0;
}
