            if (row[a] < row[b]) return true;
            if (row[b] < row[a]) return false;
            return a < b;
        });
        for (int t = 0; t < k; ++t) {
            nn[(size_t)i*k+t] = order[t];
            nw[(size_t)i*k+t] = row[order[t]];
