    std::vector<double> colmin(n, INF);
    std::vector<int> colmin_i(n, -1);
    for (int i = 0; i < n; ++i) {
        for (int t = 0; t < k; ++t) {
            int j = nn[(size_t)i*k+t];
            double c = nw[(size_t)i*k+t];
            if (c < colmin[j]) { colmin[j] = c; colmin_i[j] = i; }
