        // reachable set stays near k*depth. Use a binary heap.
        using P = std::pair<double,int>;
        std::vector<P> heap;
        for (int t = 0; t < ntodo; ++t) heap.emplace_back(d[collist[t]], collist[t]);
        std::make_heap(heap.begin(), heap.end(), std::greater<P>());
        int settled_count = 0;
        std::vector<int> settled;
        settled.reserve(n);
        while (!heap.empty()) {
            std::pop_heap(heap.begin(), heap.end(), std::greater<P>());
            auto [dj, j] = heap.back(); heap.pop_back();
            if (done[j] || dj > d[j]) continue;
