#include <vector>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <cstring>

// Gauss-Seidel epsilon-scaling auction. Returns 0 and writes assignment.
// eps_factor and nphases tuned by caller via eps_target only; internal factor fixed.

extern "C" int auction(int n, const double* C, int* rowsol, double eps_target, double factor, int start_div) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    std::vector<int> unassigned(n);

    double cmax = 0.0;
    for (int i = 0; i < n; i += 1) {
        const double* row = C + (size_t)i * n;
        // sample a few
        for (int j = 0; j < n; j += 8) {
            double v = row[j];
            if (v > cmax) cmax = v;
        }
    }
    if (cmax < 1e-12) cmax = 1.0;
    double eps = cmax / (double)start_div;

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int cursor = 0;
        long long bids = 0;
        long long max_bids = (long long)n * n * 2;
        while (nun > 0 && bids < max_bids) {
            if (cursor >= nun) cursor = 0;
            int i = unassigned[cursor];
            const double* row = C + (size_t)i * n;
            int j1 = 0;
            double v1 = -1e300, v2 = -1e300;
            const double* pr = price.data();
            int j = 0;
            int n8 = n & ~7;
            for (; j < n8; j += 8) {
                double a0 = -row[j] - pr[j];
                double a1 = -row[j+1] - pr[j+1];
                double a2 = -row[j+2] - pr[j+2];
                double a3 = -row[j+3] - pr[j+3];
                double a4 = -row[j+4] - pr[j+4];
                double a5 = -row[j+5] - pr[j+5];
                double a6 = -row[j+6] - pr[j+6];
                double a7 = -row[j+7] - pr[j+7];
#define UPD(val, jj) if (val > v1) { v2 = v1; v1 = val; j1 = jj; } else if (val > v2) v2 = val;
                UPD(a0, j) UPD(a1, j+1) UPD(a2, j+2) UPD(a3, j+3)
                UPD(a4, j+4) UPD(a5, j+5) UPD(a6, j+6) UPD(a7, j+7)
#undef UPD
            }
            for (; j < n; ++j) {
                double a = -row[j] - pr[j];
                if (a > v1) { v2 = v1; v1 = a; j1 = j; }
                else if (a > v2) v2 = a;
            }
            double bid = pr[j1] + (v1 - v2) + eps;
            int prev = owner[j1];
            price[j1] = bid;
            owner[j1] = i;
            assignment[i] = j1;
            ++bids;
            if (prev >= 0 && prev != i) {
                assignment[prev] = -1;
                unassigned[cursor] = prev;
                ++cursor;
            } else {
                unassigned[cursor] = unassigned[--nun];
            }
        }
        if (nun > 0) return -1;
        if (eps <= eps_target) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
}
