// Integer Gauss-Seidel auction with epsilon scaling.
// Costs are int32. Prices are int64.
// Bid computation still scans the row (unavoidable) but arithmetic is integer.

extern "C" int iauction(int n, const int32_t* C, int* rowsol, int32_t eps_target, int factor_num, int factor_den, int start_div) {
    std::vector<int64_t> price(n, 0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    std::vector<int> unassigned(n);

    int32_t cmax = 1;
    for (int i = 0; i < n*n; i += 11) {
        int32_t v = C[i];
        if (v > cmax) cmax = v;
    }
    int64_t eps = std::max<int64_t>(1, (int64_t)cmax / start_div);

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int cursor = 0;
        long long bids = 0;
        long long max_bids = (long long)n * n;
        while (nun > 0 && bids < max_bids) {
            if (cursor >= nun) cursor = 0;
            int i = unassigned[cursor];
            const int32_t* row = C + (size_t)i * n;
            int j1 = 0;
            int64_t v1 = INT64_MIN/4, v2 = INT64_MIN/4;
            const int64_t* pr = price.data();
            for (int j = 0; j < n; ++j) {
                int64_t val = -(int64_t)row[j] - pr[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            int64_t bid = pr[j1] + (v1 - v2) + eps;
            int prev = owner[j1];
            price[j1] = bid;
            owner[j1] = i;
            assignment[i] = j1;
            ++bids;
            if (prev >= 0 && prev != i) {
                assignment[prev] = -1;
                unassigned[cursor] = prev;
                ++cursor;
            } else {
                unassigned[cursor] = unassigned[--nun];
            }
        }
        if (nun > 0) return -1;
        if (eps <= (int64_t)eps_target) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        int64_t next = eps * factor_num / factor_den;
        if (next < (int64_t)eps_target) next = eps_target;
        if (next >= eps) next = eps - 1;
        if (next < 1 && eps_target < 1) next = 0;
        eps = next;
    }
}
