#include <algorithm>
#include <cmath>
#include <cstring>

// Auction restricted to k nearest (by cost) per row.
// If the optimal assignment lies in the kNN graph, and epsilon is small enough
// relative to cost gaps, this returns that assignment.
// Returns -1 if it fails to find a perfect matching in the subgraph.

extern "C" int auction_k(int n, const double* C, int k, int* rowsol, double eps_target, double factor) {
    if (k > n) k = n;
    std::vector<int> nn((size_t)n * k);
    std::vector<double> nw((size_t)n * k);
    std::vector<int> order(n);
    double cmax = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; ++j) order[j] = j;
        std::nth_element(order.begin(), order.begin()+k-1, order.end(),
                         [&](int a, int b){ return row[a] < row[b]; });
        for (int t = 0; t < k; ++t) {
            // partial, unsorted ok
            int j = order[t];
            // nth_element only guarantees order[k-1] is the kth; first k are the smallest but unsorted. Good.
            nn[(size_t)i*k+t] = j;
            double w = row[j];
            nw[(size_t)i*k+t] = w;
            if (w > cmax) cmax = w;
        }
    }
    // NOTE: nth_element with k-1 means elements [0,k) are the k smallest only if we use begin+k as nth.
    // std::nth_element(begin, begin+k-1, end) puts the k-th smallest at index k-1 and smaller before it.
    // So [0,k) are the k smallest. Correct.

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1), unassigned(n);
    if (cmax < 1e-12) cmax = 1;
    double eps = cmax / 4.0;

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int cursor = 0;
        long long bids = 0;
        long long max_bids = (long long)n * k * 20;
        while (nun > 0 && bids < max_bids) {
            if (cursor >= nun) cursor = 0;
            int i = unassigned[cursor];
            const int* idx = nn.data() + (size_t)i * k;
            const double* w = nw.data() + (size_t)i * k;
            int j1 = idx[0];
            double v1 = -1e300, v2 = -1e300;
            for (int t = 0; t < k; ++t) {
                int j = idx[t];
                double val = -w[t] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            double bid = price[j1] + (v1 - v2) + eps;
            int prev = owner[j1];
            price[j1] = bid;
            owner[j1] = i;
            assignment[i] = j1;
            ++bids;
            if (prev >= 0 && prev != i) {
                assignment[prev] = -1;
                unassigned[cursor] = prev;
                ++cursor;
            } else {
                unassigned[cursor] = unassigned[--nun];
            }
        }
        if (nun > 0) return -1;
        if (eps <= eps_target) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
}
