// Fast best+second using one scalar pass but with prefetch and 8-way unroll,
// plus a SIMD version that tracks per-lane max and second via blending.

static inline void best_two(const double* row, const double* price, int n,
                            int& j1, double& v1, double& v2) {
    // Per-lane running max. Then horizontal reduction, then one more pass for second
    // if second might be in another lane — actually second overall may not be the second of the max lane.
    // So: SIMD find global max index, then SIMD find max excluding that index.
    int n4 = n & ~3;
    __m256d vmax = _mm256_set1_pd(-1e300);
    int j = 0;
    for (; j < n4; j += 4) {
        __m256d r = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_xor_pd(r, _mm256_set1_pd(-0.0)); // -r
        val = _mm256_sub_pd(val, p);
        vmax = _mm256_max_pd(vmax, val);
    }
    alignas(32) double tv[4];
    _mm256_store_pd(tv, vmax);
    double m = tv[0];
    int lane = 0;
    if (tv[1] > m) { m = tv[1]; lane = 1; }
    if (tv[2] > m) { m = tv[2]; lane = 2; }
    if (tv[3] > m) { m = tv[3]; lane = 3; }
    // find index: scan lanes. To get the index we rescan — but that's another pass.
    // Instead store indices alongside. Redo with index tracking for pass 1 only once.
    // For speed, do a scalar index search only comparing to m (most won't match).
    int jbest = -1;
    for (int t = lane; t < n4; t += 4) {
        double val = -row[t] - price[t];
        if (val == m) { jbest = t; break; }
    }
    // tail
    double mt = m;
    for (int t = n4; t < n; ++t) {
        double val = -row[t] - price[t];
        if (val > mt) { mt = val; jbest = t; }
    }
    if (jbest < 0) {
        // floating compare failed due to -0 or nan; fallback scalar
        jbest = 0; mt = -row[0]-price[0];
        for (int t = 1; t < n; ++t) {
            double val = -row[t]-price[t];
            if (val > mt) { mt = val; jbest = t; }
        }
    } else if (mt > m) {
        m = mt;
    }
    // second max: SIMD max of values with jbest masked out
    __m256d v2m = _mm256_set1_pd(-1e300);
    j = 0;
    for (; j < n4; j += 4) {
        __m256d r = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_sub_pd(_mm256_xor_pd(r, _mm256_set1_pd(-0.0)), p);
        // mask out jbest if in this block
        if (jbest >= j && jbest < j + 4) {
            alignas(32) double buf[4];
            _mm256_store_pd(buf, val);
            buf[jbest - j] = -1e300;
            val = _mm256_load_pd(buf);
        }
        v2m = _mm256_max_pd(v2m, val);
    }
    _mm256_store_pd(tv, v2m);
    double s = tv[0];
    if (tv[1] > s) s = tv[1];
    if (tv[2] > s) s = tv[2];
    if (tv[3] > s) s = tv[3];
    for (int t = n4; t < n; ++t) if (t != jbest) {
        double val = -row[t] - price[t];
        if (val > s) s = val;
    }
    j1 = jbest; v1 = (jbest>=0 ? -row[jbest]-price[jbest] : m); v2 = s;
}

extern "C" int auction_avx(int n, const double* C, int* rowsol, double eps_target, double factor, int start_div) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    std::vector<int> unassigned(n);

    double cmax = 0.0;
    for (int i = 0; i < n; ++i) {
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; j += 16) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax < 1e-12) cmax = 1.0;
    double eps = cmax / (double)start_div;

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int cursor = 0;
        long long bids = 0;
        long long max_bids = (long long)n * n * 2;
        while (nun > 0 && bids < max_bids) {
            if (cursor >= nun) cursor = 0;
            int i = unassigned[cursor];
            int j1; double v1, v2;
            best_two(C + (size_t)i * n, price.data(), n, j1, v1, v2);
            double bid = price[j1] + (v1 - v2) + eps;
            int prev = owner[j1];
            price[j1] = bid;
            owner[j1] = i;
            assignment[i] = j1;
            ++bids;
            if (prev >= 0 && prev != i) {
                assignment[prev] = -1;
                unassigned[cursor] = prev;
                ++cursor;
            } else {
                unassigned[cursor] = unassigned[--nun];
            }
        }
        if (nun > 0) return -1;
        if (eps <= eps_target) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
}
