#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

// Given an assignment (row -> col), search for improving 2-swaps.
// For each row i, look at its k nearest columns. If column j is assigned to row i2,
// swap if cost(i,j)+cost(i2, col_i) < cost(i,col_i)+cost(i2,j).
// Repeat until no improvement or max passes.
// This finds the optimal assignment if the optimum differs from the start by
// swaps whose edges are in the kNN graph. Not always true, but cheap.

extern "C" int improve_swaps(int n, const double* C, int* rowsol, int k, int max_passes) {
    std::vector<int> col_of(n);
    std::vector<int> row_of(n, -1);
    for (int i = 0; i < n; ++i) {
        col_of[i] = rowsol[i];
        if (rowsol[i] < 0 || rowsol[i] >= n) return -1;
        row_of[rowsol[i]] = i;
    }
    std::vector<int> order(n);
    for (int pass = 0; pass < max_passes; ++pass) {
        bool improved = false;
        for (int i = 0; i < n; ++i) {
            const double* row = C + (size_t)i * n;
            int jcur = col_of[i];
            double ccur = row[jcur];
            // select k nearest via partial scan using a max-heap of size k
            // For speed, use nth_element on indices once per row per pass — expensive.
            // Instead scan all columns but only consider those with cost < ccur + margin? 
            // We need candidates that might help the OTHER row, so cost to i can be larger than ccur.
            // Limit to k nearest.
            for (int j = 0; j < n; ++j) order[j] = j;
            std::nth_element(order.begin(), order.begin()+k, order.end(),
                             [&](int a, int b){ return row[a] < row[b]; });
            for (int t = 0; t < k; ++t) {
                int j = order[t];
                if (j == jcur) continue;
                int i2 = row_of[j];
                if (i2 < 0 || i2 == i) continue;
                int j2 = jcur; // would go to i2
                double c_i_j = row[j];
                double c_i2_j2 = C[(size_t)i2 * n + j2];
                double c_i2_j = C[(size_t)i2 * n + j];
                double delta = (c_i_j + c_i2_j2) - (ccur + c_i2_j);
                if (delta < -1e-12) {
                    // swap
                    col_of[i] = j;
                    col_of[i2] = j2;
                    row_of[j] = i;
                    row_of[j2] = i2;
                    ccur = c_i_j;
                    jcur = j;
                    improved = true;
                }
            }
        }
        if (!improved) break;
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of[i];
    return 0;
}
