#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

struct Graph {
    int n, k;
    std::vector<int> nn;
    std::vector<double> nw;
};

static Graph build_knn(int n, const double* C, int k) {
    Graph g;
    g.n = n; g.k = k;
    g.nn.resize((size_t)n * k);
    g.nw.resize((size_t)n * k);
    std::vector<int> order(n);
    for (int i = 0; i < n; ++i) {
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; ++j) order[j] = j;
        std::nth_element(order.begin(), order.begin() + k, order.end(),
                         [&](int a, int b){ return row[a] < row[b]; });
        for (int t = 0; t < k; ++t) {
            int j = order[t];
            g.nn[(size_t)i * k + t] = j;
            g.nw[(size_t)i * k + t] = row[j];
        }
    }
    return g;
}

static int auction(const Graph& g, const double* /*C*/, int* rowsol, double eps_target, double factor) {
    int n = g.n, k = g.k;
    double cmax = 0;
    for (double w : g.nw) if (w > cmax) cmax = w;
    if (cmax < 1e-12) cmax = 1;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1), unassigned(n);
    double eps = cmax / 8.0;
    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int cursor = 0;
        long long bids = 0;
        long long max_bids = (long long)n * k * 30;
        while (nun > 0 && bids < max_bids) {
            if (cursor >= nun) cursor = 0;
            int i = unassigned[cursor];
            const int* idx = g.nn.data() + (size_t)i * k;
            const double* w = g.nw.data() + (size_t)i * k;
            int j1 = idx[0];
            double v1 = -1e300, v2 = -1e300;
            for (int t = 0; t < k; ++t) {
                double val = -w[t] - price[idx[t]];
                if (val > v1) { v2 = v1; v1 = val; j1 = idx[t]; }
                else if (val > v2) v2 = val;
            }
            double bid = price[j1] + (v1 - v2) + eps;
            int prev = owner[j1];
            price[j1] = bid;
            owner[j1] = i;
            assignment[i] = j1;
            ++bids;
            if (prev >= 0 && prev != i) {
                assignment[prev] = -1;
                unassigned[cursor] = prev;
                ++cursor;
            } else {
                unassigned[cursor] = unassigned[--nun];
            }
        }
        if (nun > 0) return -1;
        if (eps <= eps_target) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
}

// Local swap improvement using precomputed kNN of each row, but the swap
// partner edge cost is read from the full matrix (so the partner needn't be a neighbor).
static void improve(int n, const double* C, const Graph& g, int* rowsol, int passes) {
    int k = g.k;
    std::vector<int> col_of(n), row_of(n);
    for (int i = 0; i < n; ++i) {
        col_of[i] = rowsol[i];
        row_of[rowsol[i]] = i;
    }
    for (int pass = 0; pass < passes; ++pass) {
        bool improved = false;
        for (int i = 0; i < n; ++i) {
            int jcur = col_of[i];
            double ccur = C[(size_t)i * n + jcur];
            const int* idx = g.nn.data() + (size_t)i * k;
            for (int t = 0; t < k; ++t) {
                int j = idx[t];
                if (j == jcur) continue;
                int i2 = row_of[j];
                double delta = (C[(size_t)i * n + j] + C[(size_t)i2 * n + jcur])
                             - (ccur + C[(size_t)i2 * n + j]);
                if (delta < -1e-12) {
                    col_of[i] = j;
                    col_of[i2] = jcur;
                    row_of[j] = i;
                    row_of[jcur] = i2;
                    jcur = j;
                    ccur = C[(size_t)i * n + jcur];
                    improved = true;
                }
            }
        }
        if (!improved) break;
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of[i];
}

extern "C" int solve_k(int n, const double* C, int k, int* rowsol, double eps, double factor) {
    if (k > n) k = n;
    Graph g = build_knn(n, C, k);
    int rc = auction(g, C, rowsol, eps, factor);
    if (rc != 0) return rc;
    improve(n, C, g, rowsol, 4);
    return 0;
}
