#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

static void best_two_full(const double* row, const double* price, int n,
                          int& j1, double& v1, double& v2) {
    j1 = 0;
    v1 = -1e300;
    v2 = -1e300;
    int j = 0;
    int n4 = n & ~3;
    for (; j < n4; j += 4) {
        double a0 = -row[j] - price[j];
        double a1 = -row[j+1] - price[j+1];
        double a2 = -row[j+2] - price[j+2];
        double a3 = -row[j+3] - price[j+3];
        if (a0 > v1) { v2 = v1; v1 = a0; j1 = j; }
        else if (a0 > v2) v2 = a0;
        if (a1 > v1) { v2 = v1; v1 = a1; j1 = j+1; }
        else if (a1 > v2) v2 = a1;
        if (a2 > v1) { v2 = v1; v1 = a2; j1 = j+2; }
        else if (a2 > v2) v2 = a2;
        if (a3 > v1) { v2 = v1; v1 = a3; j1 = j+3; }
        else if (a3 > v2) v2 = a3;
    }
    for (; j < n; ++j) {
        double a = -row[j] - price[j];
        if (a > v1) { v2 = v1; v1 = a; j1 = j; }
        else if (a > v2) v2 = a;
    }
}

extern "C" int hybrid_auction(int n, const double* C, int k, int* rowsol,
                              double eps_target, double factor) {
    if (k > n) k = n;
    if (k < 2) k = 2;

    std::vector<int> nn((size_t)n * k);
    std::vector<double> nw((size_t)n * k);
    std::vector<int> order(n);
    double cmax = 0.0;
    for (int i = 0; i < n; ++i) {
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; ++j) order[j] = j;
        std::nth_element(order.begin(), order.begin() + k, order.end(),
                         [&](int a, int b){ return row[a] < row[b]; });
        for (int t = 0; t < k; ++t) {
            int j = order[t];
            nn[(size_t)i * k + t] = j;
            nw[(size_t)i * k + t] = row[j];
            if (row[j] > cmax) cmax = row[j];
        }
    }
    if (cmax < 1e-12) cmax = 1.0;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1), unassigned(n);

    auto run_sparse = [&](double eps) -> int {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int cursor = 0;
        long long bids = 0;
        long long max_bids = (long long)n * k * 40;
        while (nun > 0 && bids < max_bids) {
            if (cursor >= nun) cursor = 0;
            int i = unassigned[cursor];
            const int* idx = nn.data() + (size_t)i * k;
            const double* w = nw.data() + (size_t)i * k;
            int j1 = idx[0];
            double v1 = -1e300, v2 = -1e300;
            for (int t = 0; t < k; ++t) {
                double val = -w[t] - price[idx[t]];
                if (val > v1) { v2 = v1; v1 = val; j1 = idx[t]; }
                else if (val > v2) v2 = val;
            }
            double bid = price[j1] + (v1 - v2) + eps;
            int prev = owner[j1];
            price[j1] = bid;
            owner[j1] = i;
            assignment[i] = j1;
            ++bids;
            if (prev >= 0 && prev != i) {
                assignment[prev] = -1;
                unassigned[cursor] = prev;
                ++cursor;
            } else {
                unassigned[cursor] = unassigned[--nun];
            }
        }
        return nun == 0 ? 0 : -1;
    };

    double eps = cmax / 8.0;
    // sparse scaling down to a moderate epsilon (not all the way — full cleanup finishes)
    double sparse_eps = std::max(eps_target * 1000.0, 1e-5);
    while (true) {
        int rc = run_sparse(eps);
        if (rc != 0) {
            // sparse graph couldn't assign; fall through to full with whatever prices we have
            break;
        }
        if (eps <= sparse_eps) break;
        double next = eps * factor;
        if (next < sparse_eps) next = sparse_eps;
        eps = next;
    }

    // Full-matrix Gauss-Seidel at final epsilon, warm-started with prices.
    // Everyone starts unassigned; prices carry over so convergence is fast if prices are good.
    eps = eps_target;
    std::fill(assignment.begin(), assignment.end(), -1);
    std::fill(owner.begin(), owner.end(), -1);
    int nun = n;
    for (int i = 0; i < n; ++i) unassigned[i] = i;
    int cursor = 0;
    long long bids = 0;
    long long max_bids = (long long)n * n;
    while (nun > 0 && bids < max_bids) {
        if (cursor >= nun) cursor = 0;
        int i = unassigned[cursor];
        int j1; double v1, v2;
        best_two_full(C + (size_t)i * n, price.data(), n, j1, v1, v2);
        double bid = price[j1] + (v1 - v2) + eps;
        int prev = owner[j1];
        price[j1] = bid;
        owner[j1] = i;
        assignment[i] = j1;
        ++bids;
        if (prev >= 0 && prev != i) {
            assignment[prev] = -1;
            unassigned[cursor] = prev;
            ++cursor;
        } else {
            unassigned[cursor] = unassigned[--nun];
        }
    }
    if (nun > 0) return -1;
    for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
    return 0;
}
