#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

// Jacobi auction: all currently unassigned persons bid simultaneously.
// Fewer rounds than Gauss-Seidel when many are free, and each round is a
// sequential scan (still memory bound) but with better price progress per scan
// early on. We also keep a "satisfied" set and only rescan displaced persons.

extern "C" int jacobi(int n, const double* C, int* rowsol, double eps_target, double factor, int start_div) {
    std::vector<double> price(n, 0.0);
    std::vector<int> bid_j(n);
    std::vector<double> bid_p(n);
    std::vector<int> best_k(n);
    std::vector<double> best_p(n);
    std::vector<int> assignment(n, -1);
    std::vector<int> owner(n, -1);
    std::vector<int> unassigned(n);

    double cmax = 0;
    for (int i = 0; i < n; i += 4) {
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; j += 8) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax < 1e-12) cmax = 1;
    double eps = cmax / start_div;

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int rounds = 0;
        const int max_rounds = n * 2;
        while (nun > 0 && rounds < max_rounds) {
            ++rounds;
            for (int k = 0; k < nun; ++k) {
                int i = unassigned[k];
                const double* row = C + (size_t)i * n;
                int j1 = 0;
                double v1 = -1e300, v2 = -1e300;
                const double* pr = price.data();
                int j = 0, n8 = n & ~7;
                for (; j < n8; j += 8) {
                    double a0=-row[j]-pr[j], a1=-row[j+1]-pr[j+1], a2=-row[j+2]-pr[j+2], a3=-row[j+3]-pr[j+3];
                    double a4=-row[j+4]-pr[j+4], a5=-row[j+5]-pr[j+5], a6=-row[j+6]-pr[j+6], a7=-row[j+7]-pr[j+7];
#define U(val,jj) if(val>v1){v2=v1;v1=val;j1=jj;}else if(val>v2)v2=val;
                    U(a0,j) U(a1,j+1) U(a2,j+2) U(a3,j+3) U(a4,j+4) U(a5,j+5) U(a6,j+6) U(a7,j+7)
#undef U
                }
                for (; j < n; ++j) {
                    double a=-row[j]-pr[j];
                    if (a>v1){v2=v1;v1=a;j1=j;} else if(a>v2) v2=a;
                }
                bid_j[k]=j1;
                bid_p[k]=pr[j1]+(v1-v2)+eps;
            }
            std::fill(best_k.begin(), best_k.end(), -1);
            for (int k = 0; k < nun; ++k) {
                int j = bid_j[k];
                double p = bid_p[k];
                if (best_k[j] < 0 || p > best_p[j]) {
                    best_p[j] = p;
                    best_k[j] = k;
                }
            }
            for (int j = 0; j < n; ++j) {
                int k = best_k[j];
                if (k < 0) continue;
                int i = unassigned[k];
                int prev = owner[j];
                if (prev >= 0) assignment[prev] = -1;
                owner[j] = i;
                assignment[i] = j;
                price[j] = best_p[j];
            }
            int w = 0;
            for (int i = 0; i < n; ++i) if (assignment[i] < 0) unassigned[w++] = i;
            nun = w;
        }
        if (nun > 0) return -1;
        if (eps <= eps_target) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
}
