#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <cstdio>

// Forward Gauss-Seidel auction, but process people in blocks of B.
// Within a block, bids are computed against current prices (Jacobi inside block)
// so we scan B rows then update prices once. This improves ILP/cache? maybe not.
// More importantly: after a global epsilon phase reaches a coarse solution,
// only re-optimize people whose best object changed — incremental.
//
// Practical idea that CAN be 20x: 
//   Use integer costs scaled by 1e6 (known to preserve optimum on these instances
//   at 1e6 for n=200; verify for n=600). Then epsilon scaling in integer steps
//   with a LARGE initial eps and factor 0.5, but the bid scan uses SIMD integer.
//   Integer scans are ~2x faster. Combined with fewer phases if we can prove
//   eps=1 is enough after scaling by 1e6 (cost gaps >> 1).
//
// If costs are integers and eps ends at 1, auction returns an optimal integer assignment.
// Scaling by S and rounding perturbs costs by <0.5/S in original units.
// An assignment optimal for rounded costs is optimal for original if the
// optimality gap of any suboptimal assignment exceeds the perturbation.
// For n=600, total perturbation of a permutation is < n*0.5/S.
// If S=1e7, perturbation < 3e-5. We observed suboptimal local solutions had
// gaps of ~2e-8, so S=1e7 is NOT always enough to preserve the exact optimum!
// S needs gap > n/S, i.e. S > n/gap. gap can be 1e-9, S > 6e11, beyond int32.
// int64 costs with S=1e12 are OK (max cost ~2, so values ~2e12, fine for int64).
//
// So integer doesn't let us stop early. The exactness requirement is the hard part.
//
// NEW IDEA: network simplex but only scan a candidate list of edges for entering
// variable, falling back to full scan occasionally. The POT solver scans all n^2
// edges each pivot to find the most violated. If we maintain a candidate list of
// the k most violated and only full-scan every few pivots (like the candidate list
// pivot rule in network simplex), we can get the SAME pivot sequence? No — different
// pivot rule yields a different basic solution even at optimality when there are
// degenerate multiple optima.
//
// The reference uses a specific pivot rule. To match it we must either use the same
// solver or the optimum must be unique. On these geometric instances the optimum
// appears unique (auction matched emd whenever eps was small enough and the graph
// was complete). So ANY optimal assignment matches, as our full auction tests showed
// 0 mismatches. The sparse restriction was the only source of mismatches.
//
// Therefore a correct fast solver = any exact assignment algorithm.
// We need one that is 20x faster than network simplex (~0.15s) i.e. <7.5ms.
//
// Memory bandwidth: one scan of 600*600 doubles = 2.88MB. At ~10 GB/s effective
// (random-ish) that's 0.3ms per scan. 20x means we can afford about 25 full scans.
// Gauss-Seidel auction does thousands of scans. We need an algorithm with ~O(10) scans.
//
// Cost-scaling / auction with Jacobi and aggressive scaling might do it if the
// number of rounds is small. Let's count rounds.

extern "C" int jacobi_count(int n, const double* C, int* rowsol, double eps_target, double factor, int start_div, long long* out_scans) {
    std::vector<double> price(n, 0.0);
    std::vector<int> bid_j(n);
    std::vector<double> bid_p(n);
    std::vector<int> best_k(n);
    std::vector<double> best_p(n);
    std::vector<int> assignment(n, -1);
    std::vector<int> owner(n, -1);
    std::vector<int> unassigned(n);
    double cmax = 0;
    for (int i = 0; i < n*n; i += 13) if (C[i] > cmax) cmax = C[i];
    if (cmax < 1e-12) cmax = 1;
    double eps = cmax / start_div;
    long long scans = 0;
    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int rounds = 0;
        while (nun > 0 && rounds < n * 4) {
            ++rounds;
            scans += nun;
            for (int k = 0; k < nun; ++k) {
                int i = unassigned[k];
                const double* row = C + (size_t)i * n;
                int j1 = 0; double v1=-1e300, v2=-1e300;
                for (int j = 0; j < n; ++j) {
                    double a = -row[j] - price[j];
                    if (a > v1) { v2 = v1; v1 = a; j1 = j; }
                    else if (a > v2) v2 = a;
                }
                bid_j[k] = j1;
                bid_p[k] = price[j1] + (v1 - v2) + eps;
            }
            std::fill(best_k.begin(), best_k.end(), -1);
            for (int k = 0; k < nun; ++k) {
                int j = bid_j[k];
                if (best_k[j] < 0 || bid_p[k] > best_p[j]) { best_p[j]=bid_p[k]; best_k[j]=k; }
            }
            for (int j = 0; j < n; ++j) {
                int k = best_k[j];
                if (k < 0) continue;
                int i = unassigned[k];
                int prev = owner[j];
                if (prev >= 0) assignment[prev] = -1;
                owner[j] = i;
                assignment[i] = j;
                price[j] = best_p[j];
            }
            int w=0;
            for (int i=0;i<n;++i) if (assignment[i]<0) unassigned[w++]=i;
            nun=w;
        }
        if (nun > 0) { *out_scans = scans; return -1; }
        if (eps <= eps_target) {
            for (int i=0;i<n;++i) rowsol[i]=assignment[i];
            *out_scans = scans;
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
}
