#include <immintrin.h>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

// Find best and second-best of (-row[j] - price[j]) using AVX.
// Two-pass: SIMD max, then scalar locate index (rare equality), then SIMD second max.
// For n=600 this is memory bound; SIMD helps instruction throughput on the sub/max.

static inline void best_two_avx(const double* row, const double* price, int n,
                                int& j1, double& v1, double& v2) {
    const int n4 = n & ~3;
    __m256d vmax = _mm256_set1_pd(-1e300);
    int j = 0;
    for (; j < n4; j += 4) {
        __m256d r = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_sub_pd(_mm256_xor_pd(r, _mm256_set1_pd(-0.0)), p);
        vmax = _mm256_max_pd(vmax, val);
    }
    alignas(32) double tv[4];
    _mm256_store_pd(tv, vmax);
    double m = tv[0];
    if (tv[1] > m) m = tv[1];
    if (tv[2] > m) m = tv[2];
    if (tv[3] > m) m = tv[3];
    for (int t = n4; t < n; ++t) {
        double val = -row[t] - price[t];
        if (val > m) m = val;
    }
    // locate j1: compare to m. Use a tolerance-free exact compare of the computed value.
    int jbest = -1;
    for (int t = 0; t < n; ++t) {
        double val = -row[t] - price[t];
        if (val == m) { jbest = t; break; }
    }
    if (jbest < 0) {
        // fallback
        jbest = 0; m = -row[0] - price[0];
        for (int t = 1; t < n; ++t) {
            double val = -row[t] - price[t];
            if (val > m) { m = val; jbest = t; }
        }
    }
    __m256d vs = _mm256_set1_pd(-1e300);
    j = 0;
    for (; j < n4; j += 4) {
        __m256d r = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_sub_pd(_mm256_xor_pd(r, _mm256_set1_pd(-0.0)), p);
        if (jbest >= j && jbest < j + 4) {
            alignas(32) double buf[4];
            _mm256_store_pd(buf, val);
            buf[jbest - j] = -1e300;
            val = _mm256_load_pd(buf);
        }
        vs = _mm256_max_pd(vs, val);
    }
    _mm256_store_pd(tv, vs);
    double s = tv[0];
    if (tv[1] > s) s = tv[1];
    if (tv[2] > s) s = tv[2];
    if (tv[3] > s) s = tv[3];
    for (int t = n4; t < n; ++t) if (t != jbest) {
        double val = -row[t] - price[t];
        if (val > s) s = val;
    }
    j1 = jbest; v1 = m; v2 = s;
}

extern "C" int auction_gs(int n, const double* C, int* rowsol, double eps_target, double factor, int start_div) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1), unassigned(n);
    double cmax = 0;
    for (int i = 0; i < n; i += 5) {
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; j += 9) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax < 1e-12) cmax = 1;
    double eps = cmax / start_div;
    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int cursor = 0;
        long long bids = 0;
        long long max_bids = (long long)n * n * 2;
        while (nun > 0 && bids < max_bids) {
            if (cursor >= nun) cursor = 0;
            int i = unassigned[cursor];
            int j1; double v1, v2;
            best_two_avx(C + (size_t)i * n, price.data(), n, j1, v1, v2);
            double bid = price[j1] + (v1 - v2) + eps;
            int prev = owner[j1];
            price[j1] = bid;
            owner[j1] = i;
            assignment[i] = j1;
            ++bids;
            if (prev >= 0 && prev != i) {
                assignment[prev] = -1;
                unassigned[cursor] = prev;
                ++cursor;
            } else {
                unassigned[cursor] = unassigned[--nun];
            }
        }
        if (nun > 0) return -1;
        if (eps <= eps_target) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
}
