#include <pthread.h>
#include <cstdint>
#include <vector>
#include <cstring>
#include <cstdio>
#include <cstdlib>
#include <cmath>

struct Arg {
    const double* C;
    const double* price;
    int n, i0, i1;
    int* j1;
    double* v1;
    double* v2;
};

static void* worker(void* p) {
    Arg* a = (Arg*)p;
    int n = a->n;
    for (int i = a->i0; i < a->i1; ++i) {
        const double* row = a->C + (size_t)i * n;
        int bj = 0;
        double m1 = -1e300, m2 = -1e300;
        for (int j = 0; j < n; ++j) {
            double v = -row[j] - a->price[j];
            if (v > m1) { m2 = m1; m1 = v; bj = j; }
            else if (v > m2) m2 = v;
        }
        a->j1[i] = bj;
        a->v1[i] = m1;
        a->v2[i] = m2;
    }
    return nullptr;
}

extern "C" double bench_threads(int n, const double* C, int nthreads, int rounds) {
    std::vector<double> price(n, 0.1);
    std::vector<int> j1(n);
    std::vector<double> v1(n), v2(n);
    for (int r = 0; r < rounds; ++r) {
        if (nthreads == 1) {
            Arg a{C, price.data(), n, 0, n, j1.data(), v1.data(), v2.data()};
            worker(&a);
        } else {
            pthread_t th[8];
            Arg args[8];
            int chunk = (n + nthreads - 1) / nthreads;
            int live = 0;
            for (int t = 0; t < nthreads; ++t) {
                int i0 = t * chunk;
                int i1 = std::min(n, i0 + chunk);
                if (i0 >= n) break;
                args[t] = Arg{C, price.data(), n, i0, i1, j1.data(), v1.data(), v2.data()};
                pthread_create(&th[t], nullptr, worker, &args[t]);
                live++;
            }
            for (int t = 0; t < live; ++t) pthread_join(th[t], nullptr);
        }
        // touch price so compiler can't DCE across rounds — mutate slightly
        price[r % n] += 1e-9;
    }
    return v1[0];
}
