#include <pthread.h>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <atomic>

// Parallel Jacobi auction. Each round, all unassigned rows are scanned by
// NTHREADS workers. Price update is serial.

static const int MAX_THREADS = 4;

struct ScanArg {
    const double* C;
    const double* price;
    const int* unassigned;
    int n, k0, k1;
    int* bid_j;
    double* bid_p;
    double eps;
};

static void* scan_worker(void* p) {
    ScanArg* a = (ScanArg*)p;
    int n = a->n;
    const double* price = a->price;
    double eps = a->eps;
    for (int k = a->k0; k < a->k1; ++k) {
        int i = a->unassigned[k];
        const double* row = a->C + (size_t)i * n;
        int j1 = 0;
        double v1 = -1e300, v2 = -1e300;
        int j = 0;
        int n8 = n & ~7;
        for (; j < n8; j += 8) {
            double a0=-row[j]-price[j], a1=-row[j+1]-price[j+1];
            double a2=-row[j+2]-price[j+2], a3=-row[j+3]-price[j+3];
            double a4=-row[j+4]-price[j+4], a5=-row[j+5]-price[j+5];
            double a6=-row[j+6]-price[j+6], a7=-row[j+7]-price[j+7];
#define U(val,jj) if(val>v1){v2=v1;v1=val;j1=jj;}else if(val>v2)v2=val;
            U(a0,j) U(a1,j+1) U(a2,j+2) U(a3,j+3) U(a4,j+4) U(a5,j+5) U(a6,j+6) U(a7,j+7)
#undef U
        }
        for (; j < n; ++j) {
            double val = -row[j] - price[j];
            if (val > v1) { v2 = v1; v1 = val; j1 = j; }
            else if (val > v2) v2 = val;
        }
        a->bid_j[k] = j1;
        a->bid_p[k] = price[j1] + (v1 - v2) + eps;
    }
    return nullptr;
}

extern "C" int par_auction(int n, const double* C, int* rowsol, double eps_target, double factor, int start_div, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    if (nthreads > MAX_THREADS) nthreads = MAX_THREADS;

    std::vector<double> price(n, 0.0);
    std::vector<int> bid_j(n);
    std::vector<double> bid_p(n);
    std::vector<int> best_k(n);
    std::vector<double> best_p(n);
    std::vector<int> assignment(n, -1);
    std::vector<int> owner(n, -1);
    std::vector<int> unassigned(n);

    double cmax = 0;
    for (int i = 0; i < n; i += 4) {
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; j += 8) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax < 1e-12) cmax = 1;
    double eps = cmax / start_div;

    pthread_t th[MAX_THREADS];
    ScanArg args[MAX_THREADS];

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int rounds = 0;
        const int max_rounds = n * 3;
        while (nun > 0 && rounds < max_rounds) {
            ++rounds;
            int live = nthreads;
            if (nun < nthreads * 8) live = 1;
            int chunk = (nun + live - 1) / live;
            int started = 0;
            for (int t = 0; t < live; ++t) {
                int k0 = t * chunk;
                int k1 = std::min(nun, k0 + chunk);
                if (k0 >= nun) break;
                args[t] = ScanArg{C, price.data(), unassigned.data(), n, k0, k1, bid_j.data(), bid_p.data(), eps};
                if (t == live - 1 || live == 1) {
                    scan_worker(&args[t]);
                } else {
                    pthread_create(&th[t], nullptr, scan_worker, &args[t]);
                    started++;
                }
            }
            for (int t = 0; t < started; ++t) pthread_join(th[t], nullptr);

            std::fill(best_k.begin(), best_k.end(), -1);
            for (int k = 0; k < nun; ++k) {
                int j = bid_j[k];
                double p = bid_p[k];
                if (best_k[j] < 0 || p > best_p[j]) {
                    best_p[j] = p;
                    best_k[j] = k;
                }
            }
            for (int j = 0; j < n; ++j) {
                int k = best_k[j];
                if (k < 0) continue;
                int i = unassigned[k];
                int prev = owner[j];
                if (prev >= 0) assignment[prev] = -1;
                owner[j] = i;
                assignment[i] = j;
                price[j] = best_p[j];
            }
            int w = 0;
            for (int i = 0; i < n; ++i) if (assignment[i] < 0) unassigned[w++] = i;
            nun = w;
        }
        if (nun > 0) return -1;
        if (eps <= eps_target) {
            for (int i = 0; i < n; ++i) rowsol[i] = assignment[i];
            return 0;
        }
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
}
